hl.monitor({ output = "", mode = "preferred", position = "auto", scale = "auto" })

-- Generated by vicOS from vicos.hyprland.monitors.
local has_nixvars, nixvars = pcall(require, "nixvars")
if not has_nixvars or type(nixvars) ~= "table" then
    nixvars = {}
end

for _, monitor in ipairs(nixvars.monitors or {}) do
    hl.monitor(monitor)
end

-- Monitor rules are registered above; create the configured headless outputs
-- afterwards so Hyprland applies those rules on creation.
for _, output in ipairs(nixvars.virtual or {}) do
    if hl.get_monitor(output) == nil then
        hl.exec_cmd("hyprctl output create headless " .. output)
    end
end

if nixvars.primary then
    for i = 1, 10 do
        hl.workspace_rule({ workspace = tostring(i), monitor = nixvars.primary, default = i == 1, persistent = i == 1 })
    end
end

hl.config({
    input = {
        kb_layout = "us",
        kb_variant = "altgr-intl",
        ["touchpad.natural_scroll"] = true,
        numlock_by_default = true,
    },
})

hl.layer_rule({ name = "vicinae-blur", match = { namespace = "vicinae" }, blur = true, ignore_alpha = 0 })
hl.layer_rule({ name = "vicinae-no-anim", match = { namespace = "vicinae" }, no_anim = true })

hl.bind("SUPER + T", hl.dsp.exec_cmd("uwsm app -- xdg-terminal-exec"))
hl.bind("SUPER + E", hl.dsp.exec_cmd('uwsm app -- xdg-open "$HOME"'))
-- vicinae runs as a user service and launches apps through uwsm itself.
hl.bind("SUPER + A", hl.dsp.exec_cmd("vicinae toggle"))
hl.bind("SUPER + R", hl.dsp.exec_cmd("vicinae toggle"))
hl.bind("SUPER + V", hl.dsp.exec_cmd("vicinae vicinae://launch/clipboard/history"))
hl.bind("SUPER + F", hl.dsp.exec_cmd('uwsm app -- "$(xdg-settings get default-web-browser)"'))
hl.bind("SUPER + C", hl.dsp.exec_cmd('uwsm app -- "$(xdg-mime query default text/plain)"'))
hl.bind("SUPER + Q", hl.dsp.window.close())
hl.bind("SUPER + W", hl.dsp.window.float())
hl.bind("ALT + RETURN", hl.dsp.window.fullscreen())
hl.bind("SUPER + L", hl.dsp.exec_cmd("loginctl lock-session"))
hl.bind("CTRL + ALT + DELETE", hl.dsp.exec_cmd("uwsm stop"))

hl.bind("SUPER + mouse:272", hl.dsp.window.drag(), { mouse = true })
hl.bind("SUPER + mouse:273", hl.dsp.window.resize(), { mouse = true })

hl.bind("XF86AudioRaiseVolume", hl.dsp.exec_cmd("pamixer -i 5"))
hl.bind("XF86AudioLowerVolume", hl.dsp.exec_cmd("pamixer -d 5"))
hl.bind("XF86AudioMute", hl.dsp.exec_cmd("pamixer -t"))
hl.bind("XF86AudioMicMute", hl.dsp.exec_cmd("pamixer --default-source -t"))
hl.bind("XF86AudioPlay", hl.dsp.exec_cmd("playerctl play-pause"))
hl.bind("XF86AudioNext", hl.dsp.exec_cmd("playerctl next"))
hl.bind("XF86AudioPrev", hl.dsp.exec_cmd("playerctl previous"))
hl.bind("XF86MonBrightnessUp", hl.dsp.exec_cmd("brightnessctl set +5%"))
hl.bind("XF86MonBrightnessDown", hl.dsp.exec_cmd("brightnessctl set 5%-"))
hl.bind("Print", hl.dsp.exec_cmd("hyprshot -m region"))
hl.bind("SUPER + SHIFT + S", hl.dsp.exec_cmd("hyprshot -m region"))

for i = 1, 10 do
    local key = i == 10 and "0" or tostring(i)
    hl.bind("SUPER + " .. key, hl.dsp.focus({ workspace = i }))
    hl.bind("SUPER + SHIFT + " .. key, hl.dsp.window.move({ workspace = i }))
end
